class RingBuffer(T)
  def initialize(@capacity : Int32)
    @buffer = Array(T | Nil).new(@capacity, nil)
    @head = 0
    @tail = 0
    @size = 0
  end

  def push(value : T) : self
    @buffer[@tail] = value
    @tail = (@tail + 1) % @capacity
    if full?
      @head = (@head + 1) % @capacity
    else
      @size += 1
    end
    self
  end

  def pop : T
    raise IndexError.new("buffer is empty") if empty?
    value = @buffer[@head].not_nil!
    @buffer[@head] = nil
    @head = (@head + 1) % @capacity
    @size -= 1
    value
  end

  def empty? : Bool
    @size == 0
  end

  def full? : Bool
    @size == @capacity
  end

  getter size : Int32
end

