class TagRegistry
  def initialize
    @tags = Set(String).new
  end

  def add(tag : String) : self
    @tags.add(tag)
    self
  end

  def add_all(tags : Enumerable(String)) : self
    tags.each { |t| @tags.add(t) }
    self
  end

  def includes?(tag : String) : Bool
    @tags.includes?(tag)
  end

  def common_with(other : TagRegistry) : Set(String)
    @tags & other.@tags
  end

  def exclusive_to(other : TagRegistry) : Set(String)
    @tags - other.@tags
  end

  def combined_with(other : TagRegistry) : Set(String)
    @tags | other.@tags
  end

  def size : Int32
    @tags.size
  end
end

