class FrequencyCounter(T)
  def initialize
    @counts = {} of T => Int32
  end

  def tally(item : T) : Nil
    @counts[item] = (@counts[item]? || 0) + 1
  end

  def top(n : Int32) : Array(NamedTuple(item: T, count: Int32))
    @counts
      .to_a
      .sort_by! { |_, c| -c }
      .first(n)
      .map { |item, count| {item: item, count: count} }
  end

  def count_for(item : T) : Int32
    @counts[item]? || 0
  end

  def empty? : Bool
    @counts.empty?
  end
end

