class TokenBucket
  def initialize(capacity : Int32, refill_rate : Float64)
    raise ArgumentError.new("capacity must be positive, got #{capacity}") unless capacity > 0
    raise ArgumentError.new("refill_rate must be positive, got #{refill_rate}") unless refill_rate > 0.0
    @capacity = capacity
    @refill_rate = refill_rate
    @available = capacity.to_f
  end

  def consume(tokens : Int32 = 1) : Bool
    raise ArgumentError.new("tokens must be >= 1, got #{tokens}") unless tokens >= 1
    return false if @available < tokens
    @available -= tokens
    true
  end

  def refill(elapsed_seconds : Float64) : Nil
    @available = (@available + @refill_rate * elapsed_seconds).clamp(0.0, @capacity.to_f)
  end
end

