require "json"

class WordFrequency
  def initialize(text : String)
    @counts = Hash(String, Int32).new(0)
    text.scan(/[a-zA-Z]+/) do |m|
      @counts[m[0].downcase] += 1
    end
  end

  def top(n : Int32) : Array(NamedTuple(word: String, count: Int32))
    @counts
      .to_a
      .sort_by { |_word, count| -count }
      .first(n)
      .map { |word, count| {word: word, count: count} }
  end

  def total_unique : Int32
    @counts.size
  end
end
